  const agl = Math.trunc(nx[4] * (g(1) ** 2 * g(7) / wgt ** 2 * (g(3) ** 2 / wgt ** 2) * g(9) ** 3) ** 0.25) + 1;
  const spd = Math.trunc(nx[5] * (g(1) * g(7) ** 2 / wgt ** 2 * (g(2) ** 2 / wgt ** 2) * g(3) ** 3) ** 0.25) + 1;
  const cst = Math.trunc((wgt * 10 + g(2) * 2 + g(3) * 3 + g(6) * 2 + g(8) * 2 + g(9) * 3) / 22) + 1;
